/// <summary>
/// Handler class for <c>PriceDiscAdm</c> form
/// </summary>
class GUPPriceDiscAdmFormEventHandler
{  
}

Method.Source:
    [FormEventHandler(formStr(PriceDiscAdm), FormEventType::Initialized)]
    public static void PriceDiscAdm_OnInitialized(xFormRun _sender, FormEventArgs _e)
    {
        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            FormDataSource      fdsPriceDiscAdmTrans = _sender.dataSource(formDataSourceStr(PriceDiscAdm, PriceDiscAdmTrans));
            PriceDiscAdmTable   priceDiscAdmTable = _sender.args().record();
            boolean             isPricingEnabled = PriceDiscAdmName::find(priceDiscAdmTable.JournalName).PriceDiscPriceAttributeEnable;
            boolean             isPosted = priceDiscAdmTable.Posted;

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, Relation)).allowEdit(!isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, relation)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, AccountCode)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, AccountCode)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, AccountRelation)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, AccountRelation)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, ItemCode)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, ItemCode)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, ItemRelation)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, ItemRelation)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, Percent1)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, Percent1)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, Percent2)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, Percent2)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, GenericCurrency)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, GenericCurrency)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, PDSCalculationId)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, PDSCalculationId)).allowEdit(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, SearchAgain)).visible(!isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, SearchAgain)).allowEdit(!isPricingEnabled);

            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscIcon)).visible(!isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscAdmSearch)).visible(!isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, PDSCalculationTable)).visible(!isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscAdmCopy)).visible(!isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, AddProductsButton)).visible(!isPricingEnabled);

            fdsPriceDiscAdmTrans.insertIfEmpty(!isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, PriceComponentCombination)).visible(isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, PriceComponentCombination)).allowEdit(false);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, PriceApplyAdjustment)).visible(isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, PriceApplyAdjustment)).allowEdit(isPricingEnabled);

            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, UnitAppliesToAll)).visible(isPricingEnabled);
            fdsPriceDiscAdmTrans.object(fieldNum(PriceDiscAdmTrans, UnitAppliesToAll)).allowEdit(isPricingEnabled);

            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscAdmTrans_PricingAttributeGroupNameHeader)).visible(isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscAdmTrans_PricingAttributeGroupNameLine)).visible(isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscAdmTrans_PricingAttributeDetailsHeader)).visible(isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, PriceDiscAdmTrans_PricingAttributeDetailsLine)).visible(isPricingEnabled);

            _sender.design().controlName(formControlStr(PriceDiscAdm, GUPPriceDiscPriceAttributeGroupEdit)).visible(isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, GUPPriceDiscPriceAttributeGroupCopy)).visible(isPricingEnabled);
            _sender.design().controlName(formControlStr(PriceDiscAdm, GUPPriceDiscPriceAttributeGroupSearch)).visible(isPricingEnabled);

            _sender.design().controlName(formControlStr(PriceDiscAdm, GUPPriceDiscPriceAttributeGroupEdit)).enabled(!isPosted);
            _sender.design().controlName(formControlStr(PriceDiscAdm, GUPPriceDiscPriceAttributeGroupCopy)).enabled(!isPosted);
            _sender.design().controlName(formControlStr(PriceDiscAdm, GUPPriceDiscPriceAttributeGroupSearch)).enabled(!isPosted);
        }
    }
